-- ==========================================================================
-- W6 / R10 - CONCURRENCY AND VOLATILITY, VALIDATED THOROUGHLY
-- ==========================================================================
-- Nikhil's assigned action item. Snowflake already guarantees part of this,
-- so the tests below are deliberately split into what is GUARANTEED (verify
-- cheaply, do not belabour) and what is NOT (where the real risk sits).
--
-- GUARANTEED by Using Sequences, verbatim:
--   "All values generated by a sequence are globally unique as long as the
--    sign of the sequence interval does not change. Concurrent queries never
--    observe the same value, and values within a single query are always
--    distinct."
--   => Two tables drawing from one sequence CANNOT collide. T4.1-T4.2 confirm
--      the guarantee holds through the FUNCTION WRAPPER, which is the part
--      Snowflake says nothing about.
--
-- NOT GUARANTEED, and where failures will actually come from:
--   * volatility  - IMMUTABLE/MEMOIZABLE fold the call (T4.4-T4.6). This is
--                   the real hazard: it is silent and corrupts the keyspace.
--   * invocation count per row (T4.3)
--   * composed-key uniqueness across regions - a scheme property, not a
--     Snowflake one (T4.7)
--
-- HOW TO RUN THE CONCURRENT PARTS: T4.1 and T4.2 must run in SEPARATE
-- SESSIONS AT THE SAME TIME. Open N worksheets, or drive it from a script
-- with N threads. Running them one after another proves nothing about
-- concurrency.
-- ==========================================================================

-- USE SCHEMA <scratch_db>.<scratch_schema>;

-- --------------------------------------------------------------------------
-- SETUP - one shared sequence, several target tables, one shared function
-- --------------------------------------------------------------------------
CREATE OR REPLACE SEQUENCE w6_shared_seq START 1 INCREMENT 1;

CREATE OR REPLACE TABLE w6_region_map (REGION_NAME VARCHAR(100), REGION_CODE NUMBER(9,0));
INSERT INTO w6_region_map VALUES ('North America', 1), ('EU', 2), ('APAC', 3);

-- The function under test. VOLATILE is explicit, not inherited from the
-- default, and the cast is in the BODY because a SQL UDF's declared NUMBER
-- precision and scale are ignored (see feasibility.md R6/C7).
CREATE OR REPLACE FUNCTION w6_regional_key(region_name VARCHAR)
RETURNS NUMBER(38,0)
VOLATILE
COMMENT = 'VOLATILE is REQUIRED. IMMUTABLE or MEMOIZABLE would return one key for every row - see W6 C2.'
AS
$$
    CAST(
        (SELECT m.REGION_CODE FROM w6_region_map m WHERE m.REGION_NAME = region_name)
        * 1000000000000000 + w6_shared_seq.NEXTVAL
    AS NUMBER(38,0))
$$;

CREATE OR REPLACE TABLE w6_keys_employee (K NUMBER(38,0), SRC VARCHAR(50), SESSION_TAG VARCHAR(50));
CREATE OR REPLACE TABLE w6_keys_job      (K NUMBER(38,0), SRC VARCHAR(50), SESSION_TAG VARCHAR(50));
CREATE OR REPLACE TABLE w6_keys_office   (K NUMBER(38,0), SRC VARCHAR(50), SESSION_TAG VARCHAR(50));

-- --------------------------------------------------------------------------
-- T4.1  THREE TABLES, ONE FUNCTION, ONE SEQUENCE, ALL AT ONCE
--       Run each INSERT in its own session, started together. 10k rows each
--       so the windows genuinely overlap.
-- --------------------------------------------------------------------------
-- SESSION A:
INSERT INTO w6_keys_employee (K, SRC, SESSION_TAG)
SELECT w6_regional_key('North America'), 'EMPLOYEE', CURRENT_SESSION()
FROM TABLE(GENERATOR(ROWCOUNT => 10000));

-- SESSION B:
INSERT INTO w6_keys_job (K, SRC, SESSION_TAG)
SELECT w6_regional_key('North America'), 'JOB', CURRENT_SESSION()
FROM TABLE(GENERATOR(ROWCOUNT => 10000));

-- SESSION C:
INSERT INTO w6_keys_office (K, SRC, SESSION_TAG)
SELECT w6_regional_key('North America'), 'OFFICE', CURRENT_SESSION()
FROM TABLE(GENERATOR(ROWCOUNT => 10000));

-- --------------------------------------------------------------------------
-- T4.2  THE ASSERTION - no key issued twice, across all three tables
-- --------------------------------------------------------------------------
WITH all_keys AS (
    SELECT K, SRC, SESSION_TAG FROM w6_keys_employee
    UNION ALL SELECT K, SRC, SESSION_TAG FROM w6_keys_job
    UNION ALL SELECT K, SRC, SESSION_TAG FROM w6_keys_office
)
SELECT COUNT(*)                                        AS total_keys,
       COUNT(DISTINCT K)                               AS distinct_keys,
       COUNT(*) - COUNT(DISTINCT K)                    AS duplicates,
       COUNT(DISTINCT SESSION_TAG)                     AS sessions_involved,
       CASE WHEN COUNT(*) = COUNT(DISTINCT K) THEN 'PASS - R10 holds'
            ELSE 'FAIL - key reuse across concurrent loads' END AS verdict
FROM all_keys;
-- EXPECT: total = 30000, distinct = 30000, duplicates = 0, sessions = 3.
-- sessions_involved < 3 means the inserts did NOT overlap - the test did not
-- actually run concurrently and must be redone. --------------------- PASS/FAIL

-- T4.2b  Which table did each duplicate come from, if any? Only meaningful
--        if T4.2 failed; tells you whether reuse is within or across tables.
WITH all_keys AS (
    SELECT K, SRC FROM w6_keys_employee
    UNION ALL SELECT K, SRC FROM w6_keys_job
    UNION ALL SELECT K, SRC FROM w6_keys_office
)
SELECT K, COUNT(*) AS times_issued, LISTAGG(DISTINCT SRC, ', ') AS issued_to
FROM all_keys GROUP BY K HAVING COUNT(*) > 1
ORDER BY times_issued DESC LIMIT 20;
-- EXPECT: zero rows. ----------------------------------------------- PASS/FAIL

-- --------------------------------------------------------------------------
-- T4.3  INVOCATION COUNT - did 30000 rows consume ~30000 values?
--       Gaps are fine and expected. Consumption far above the row count means
--       the function ran more than once per row, which matters because every
--       extra invocation is a wasted key.
-- --------------------------------------------------------------------------
SELECT w6_shared_seq.NEXTVAL AS seq_next_after_30k;
-- Compare against 30000. Record the number; do not treat a modest excess as
-- failure - treat a multiple as one. ------------------------------- PASS/FAIL

-- Snowflake also reports this directly for the statement:
-- SELECT QUERY_ID, QUERY_TEXT, ROWS_PRODUCED
-- FROM TABLE(INFORMATION_SCHEMA.QUERY_HISTORY())
-- WHERE QUERY_TEXT ILIKE '%w6_keys_employee%' ORDER BY START_TIME DESC LIMIT 5;

-- --------------------------------------------------------------------------
-- T4.4  THE SILENT KILLER - IMMUTABLE on the same function
--       Every row passes identical arguments, so IMMUTABLE lets Snowflake
--       reuse one result. CREATE FUNCTION: "This guarantee is not checked.
--       Specifying IMMUTABLE for a UDF that returns different values for the
--       same input will result in undefined behavior."
--       Run this to SEE the failure, so the prohibition is evidenced, not
--       asserted. Never ship this form.
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION w6_regional_key_immutable(region_name VARCHAR)
RETURNS NUMBER(38,0)
IMMUTABLE                      -- DELIBERATELY WRONG. This is a negative test.
AS
$$
    CAST(
        (SELECT m.REGION_CODE FROM w6_region_map m WHERE m.REGION_NAME = region_name)
        * 1000000000000000 + w6_shared_seq.NEXTVAL
    AS NUMBER(38,0))
$$;

WITH probe AS (
    SELECT w6_regional_key_immutable('North America') AS k
    FROM TABLE(GENERATOR(ROWCOUNT => 1000))
)
SELECT COUNT(*) AS rows_generated, COUNT(DISTINCT k) AS distinct_keys,
       CASE WHEN COUNT(DISTINCT k) = COUNT(*) THEN 'no folding observed here'
            WHEN COUNT(DISTINCT k) = 1 THEN 'CONFIRMED - one key for 1000 rows'
            ELSE 'partial folding' END AS verdict
FROM probe;
-- EXPECT: distinct_keys = 1, or some number far below 1000.
-- If distinct_keys = 1000, folding did not happen ON THIS RUN - that is NOT
-- a clean bill of health. "Undefined behavior" means it may fold on a larger
-- warehouse, a different plan, or next release. The prohibition stands on the
-- documentation, not on this result. ------------------------------- PASS/FAIL

-- --------------------------------------------------------------------------
-- T4.5  Same again for MEMOIZABLE, which the SQL handler also accepts.
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION w6_regional_key_memo(region_name VARCHAR)
RETURNS NUMBER(38,0)
MEMOIZABLE                     -- DELIBERATELY WRONG. Negative test.
AS
$$
    CAST(
        (SELECT m.REGION_CODE FROM w6_region_map m WHERE m.REGION_NAME = region_name)
        * 1000000000000000 + w6_shared_seq.NEXTVAL
    AS NUMBER(38,0))
$$;
-- EXPECT: either refused at CREATE, or folds like T4.4. Record which.
-- ------------------------------------------------------------------ PASS/FAIL

WITH probe AS (
    SELECT w6_regional_key_memo('North America') AS k FROM TABLE(GENERATOR(ROWCOUNT => 1000))
)
SELECT COUNT(*) AS rows_generated, COUNT(DISTINCT k) AS distinct_keys FROM probe;

-- --------------------------------------------------------------------------
-- T4.6  Confirm the SHIPPING function declares what we think it declares.
--       Guards against someone "optimising" it later.
-- --------------------------------------------------------------------------
SHOW FUNCTIONS LIKE 'W6_REGIONAL_KEY%';
SELECT "name", "is_memoizable" FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()));
-- Also available account-wide:
-- SELECT FUNCTION_NAME, VOLATILITY FROM SNOWFLAKE.ACCOUNT_USAGE.FUNCTIONS
-- WHERE FUNCTION_NAME ILIKE 'W6_REGIONAL_KEY%' AND DELETED IS NULL;
-- EXPECT: the shipping function VOLATILE, not memoizable. ---------- PASS/FAIL

-- --------------------------------------------------------------------------
-- T4.7  CROSS-REGION UNIQUENESS under concurrency - R12, not R10, but this
--       is the only place all three regions run at once.
--       Run the three INSERTs in three SEPARATE SESSIONS, together.
-- --------------------------------------------------------------------------
CREATE OR REPLACE TABLE w6_keys_multiregion (K NUMBER(38,0), REGION VARCHAR(50));

-- SESSION A:
INSERT INTO w6_keys_multiregion SELECT w6_regional_key('North America'), 'North America'
FROM TABLE(GENERATOR(ROWCOUNT => 5000));
-- SESSION B:
INSERT INTO w6_keys_multiregion SELECT w6_regional_key('EU'), 'EU'
FROM TABLE(GENERATOR(ROWCOUNT => 5000));
-- SESSION C:
INSERT INTO w6_keys_multiregion SELECT w6_regional_key('APAC'), 'APAC'
FROM TABLE(GENERATOR(ROWCOUNT => 5000));

SELECT COUNT(*) AS total, COUNT(DISTINCT K) AS distinct_keys,
       COUNT(*) - COUNT(DISTINCT K) AS duplicates,
       COUNT(DISTINCT REGION) AS regions,
       CASE WHEN COUNT(*) = COUNT(DISTINCT K) THEN 'PASS' ELSE 'FAIL' END AS verdict
FROM w6_keys_multiregion;
-- EXPECT: 15000 / 15000 / 0 / 3. ----------------------------------- PASS/FAIL

-- T4.7b  Does every key decode back to the region that issued it? (R13)
SELECT REGION,
       COUNT(*) AS keys_issued,
       SUM(CASE WHEN FLOOR(K / 1000000000000000) = m.REGION_CODE THEN 1 ELSE 0 END) AS decode_correct,
       CASE WHEN COUNT(*) = SUM(CASE WHEN FLOOR(K / 1000000000000000) = m.REGION_CODE THEN 1 ELSE 0 END)
            THEN 'PASS' ELSE 'FAIL' END AS verdict
FROM w6_keys_multiregion k
JOIN w6_region_map m ON m.REGION_NAME = k.REGION
GROUP BY REGION;
-- EXPECT: decode_correct = keys_issued for every region. ----------- PASS/FAIL

-- --------------------------------------------------------------------------
-- T4.8  INTERVAL SIGN - the documented way to break uniqueness
--       "Changing the sequence interval from positive to negative, or vice
--       versa, may result in duplicates." Not a test to pass, a constraint to
--       record: once keys are issued, INCREMENT must never be flipped.
-- --------------------------------------------------------------------------
-- DO NOT RUN against anything real. Documented here so the constraint is
-- visible in the test pack rather than only in prose:
--   ALTER SEQUENCE w6_shared_seq SET INCREMENT = -1;   -- NEVER do this
-- ------------------------------------------------------------- CONSTRAINT ONLY

-- --------------------------------------------------------------------------
-- TEARDOWN
-- --------------------------------------------------------------------------
DROP FUNCTION IF EXISTS w6_regional_key(VARCHAR);
DROP FUNCTION IF EXISTS w6_regional_key_immutable(VARCHAR);
DROP FUNCTION IF EXISTS w6_regional_key_memo(VARCHAR);
DROP TABLE    IF EXISTS w6_keys_employee;
DROP TABLE    IF EXISTS w6_keys_job;
DROP TABLE    IF EXISTS w6_keys_office;
DROP TABLE    IF EXISTS w6_keys_multiregion;
DROP TABLE    IF EXISTS w6_region_map;
DROP SEQUENCE IF EXISTS w6_shared_seq;

-- ==========================================================================
-- WHAT "R10 VALIDATED THOROUGHLY" MEANS WHEN THIS PACK IS DONE
-- ==========================================================================
--  T4.2   30000 keys from 3 concurrent sessions, 0 duplicates, 3 sessions seen
--  T4.3   consumption proportional to rows, invocation count recorded
--  T4.4   IMMUTABLE folding demonstrated, or documented as undefined anyway
--  T4.5   MEMOIZABLE behaviour recorded
--  T4.6   shipping function proven VOLATILE and not memoizable
--  T4.7   15000 keys across 3 concurrent regions, 0 duplicates
--  T4.7b  every key decodes to its issuing region
--  T4.8   interval-sign constraint recorded in the build standard
--
-- Anything short of this is a partial answer to the action item.
-- ==========================================================================
